import numpy as np

test_grid = [list(map(int, line.split())) for line in test_input.strip().split('\n')]
grid_arr = np.array(test_grid)

def solve_final(input_grid):
    top_frame, bottom_frame = 1, 25
    left_frame, right_frame = 1, 25

    top_int, bottom_int = top_frame + 1, bottom_frame - 1
    left_int, right_int = left_frame + 1, right_frame - 1

    output = np.zeros((input_grid.shape[0], input_grid.shape[1]), dtype=int)

    # Copy frame
    for r in range(top_frame, bottom_frame + 1):
        for c in range(left_frame, right_frame + 1):
            output[r, c] = 5

    # Fill interior with alternating concentric layers
    for r in range(top_int, bottom_int + 1):
        for c in range(left_int, right_int + 1):
            d_top = r - top_int
            d_bottom = bottom_int - r
            d_left = c - left_int
            d_right = right_int - c

            dist = min(d_top, d_bottom, d_left, d_right)

            if dist % 2 == 0:
                output[r, c] = 2
            else:
                output[r, c] = 5

    return output.tolist()

result = solve_final(grid_arr)
solution_json = {"action": "submit", "grid": result}
